 @SuppressWarnings("deprecation") private void applyNativeLocale(){java.util.Locale locale=new java.util.Locale(language());java.util.Locale.setDefault(locale);Configuration config=new Configuration(getResources().getConfiguration());config.setLocale(locale);config.setLayoutDirection(locale);getResources().updateConfiguration(config,getResources().getDisplayMetrics());}
